declare(strict_types=1);

if (PHP_SAPI !== 'cli') {
    http_response_code(404);
    exit;
}

// Generated from the checked policy files. Original hashes protect local edits.
$manifest = json_decode(<<<'WZ_POLICY_PAYLOAD'
{
  "includes/policies.php": {
