WZ_POLICY_PAYLOAD, true, 512, JSON_THROW_ON_ERROR);

function wz_policy_prompt(string $label, string $default = '', bool $email = false, bool $phone = false): string
{
    while (true) {
        echo $label . ($default !== '' ? ' [' . $default . ']' : '') . ': ';
        $line = fgets(STDIN);
        if ($line === false) {
            throw new RuntimeException('Business details were not completed. No website files have been changed.');
        }
        $value = trim($line);
        if ($value === '') {
            $value = $default;
        }
        $digits = preg_replace('/\D/', '', $value);
        if ($value !== '' && strlen($value) <= 5000 && !preg_match('/[\x00-\x1f\x7f]/', $value)
            && (!$email || filter_var($value, FILTER_VALIDATE_EMAIL))
            && (!$phone || (strlen($digits) >= 7 && strlen($digits) <= 15))) {
            return $value;
        }
        echo "Please enter a valid, complete value.\n";
    }
}

$root = realpath(getcwd() ?: '');
$backupDirectory = '';
$installed = [];
$originals = [];
$changes = [];
$staged = [];
$lock = null;

try {
    if (!$root || !is_file($root . '/includes/bootstrap.php') || !is_file($root . '/includes/database.php')) {
        throw new RuntimeException('Run this command from the Wedding Za website folder: cd ~/public_html');
    }
    if (!function_exists('token_get_all') || !function_exists('gzdecode') || !is_writable(dirname($root))) {
        throw new RuntimeException('PHP tokenizer, zlib and a writable folder outside public_html are required.');
    }
    if (stat($root)['dev'] !== stat(dirname($root))['dev']) {
        throw new RuntimeException('The backup folder and website must be on the same filesystem.');
    }

    $lock = fopen(dirname($root) . '/.weddingza-policy-update.lock', 'c');
    if (!$lock || !flock($lock, LOCK_EX | LOCK_NB)) {
        throw new RuntimeException('Another policy update is running. Try again after it finishes.');
    }
    chmod(dirname($root) . '/.weddingza-policy-update.lock', 0600);

    // Every source, destination and payload is checked before asking for details.
    foreach ($manifest as $relativePath => $entry) {
        $path = $root . '/' . $relativePath;
        $parent = realpath(dirname($path));
        if (!$parent || !str_starts_with($parent . '/', $root . '/') || !is_writable($parent) || is_link($path)) {
            throw new RuntimeException('Unsafe or unwritable path: ' . $relativePath . '.');
        }
        $compressed = base64_decode($entry['content_gzip_base64'], true);
        $updated = $compressed === false ? false : gzdecode($compressed);
        if ($updated === false || !hash_equals($entry['sha256'], hash('sha256', $updated))) {
            throw new RuntimeException('Invalid update payload: ' . $relativePath . '.');
        }
        if (str_ends_with($relativePath, '.php')) {
            token_get_all($updated, TOKEN_PARSE);
        }
        $original = is_file($path) ? file_get_contents($path) : null;
        if ($original === false || (file_exists($path) && (!is_file($path) || !is_writable($path)))) {
            throw new RuntimeException('Cannot read or update ' . $relativePath . '.');
        }
        $originals[$relativePath] = $original;
        if ($original !== null && hash_equals($entry['sha256'], hash('sha256', $original))) {
            continue;
        }
        if (($original === null && $entry['previous_sha256'] !== null)
            || ($original !== null && ($entry['previous_sha256'] === null
                || !hash_equals($entry['previous_sha256'], hash('sha256', $original))))) {
            throw new RuntimeException('The file ' . $relativePath . ' has a different version or local edits. No website files have been changed.');
        }
        $changes[$relativePath] = $updated;
    }

    $detailsPath = 'includes/policy-details.local.php';
    $detailsFile = $root . '/' . $detailsPath;
    if (is_link($detailsFile) || (file_exists($detailsFile) && (!is_file($detailsFile) || !is_writable($detailsFile)))) {
        throw new RuntimeException('Cannot safely update the public business-details file.');
    }
    $details = [];
    $originals[$detailsPath] = is_file($detailsFile) ? file_get_contents($detailsFile) : null;
    if ($originals[$detailsPath] === false) {
        throw new RuntimeException('Cannot read the public business-details file.');
    }
    if ($originals[$detailsPath] !== null) {
        token_get_all($originals[$detailsPath], TOKEN_PARSE);
        $details = require $detailsFile;
        if (!is_array($details)) {
            throw new RuntimeException('The public business-details file must return an array.');
        }
    }
    $updateDetails = in_array('--update-details', $argv, true);
    $fields = [
        'operator_name' => ['Legal business/operator name', ''],
        'postal_address' => ['Full business address, city, state and PIN (include branches if any)', ''],
        'support_phone' => ['Customer support and grievance phone', ''],
        'support_email' => ['Customer support email', 'info@weddingza.com'],
        'grievance_officer_name' => ['Name of the person handling customer complaints', ''],
        'grievance_officer_designation' => ['Grievance officer designation', 'Grievance Officer'],
        'grievance_email' => ['Grievance email', 'info@weddingza.com'],
    ];
    $detailsChanged = false;
    echo "Wedding Za policy update\n";
    echo "Use real business details. They will be displayed on all three policy pages.\n";
    echo "For a sole proprietor, use the proprietor's legal name and trading name.\n";
    echo "The named grievance officer must handle complaints at the contact details you enter.\n";
    foreach ($fields as $key => [$label, $default]) {
        $current = is_string($details[$key] ?? null) ? trim($details[$key]) : '';
        $email = in_array($key, ['support_email', 'grievance_email'], true);
        $phone = $key === 'support_phone';
        $digits = preg_replace('/\D/', '', $current);
        $valid = $current !== '' && (!$email || filter_var($current, FILTER_VALIDATE_EMAIL))
            && (!$phone || (strlen($digits) >= 7 && strlen($digits) <= 15));
        if ($updateDetails || !$valid) {
            $details[$key] = wz_policy_prompt($label, $valid ? $current : $default, $email, $phone);
            $detailsChanged = true;
        }
    }
    if ($originals[$detailsPath] === null || $detailsChanged) {
        if (!is_string($details['effective_date'] ?? null) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $details['effective_date'])) {
            $details['effective_date'] = (new DateTimeImmutable('now', new DateTimeZone('Asia/Kolkata')))->format('Y-m-d');
        }
        $detailsSource = "<?php\n\n// Public business information; this file contains no credentials.\n"
            . "if (realpath(\$_SERVER['SCRIPT_FILENAME'] ?? '') === __FILE__) {\n    http_response_code(404);\n    exit;\n}\n\nreturn "
            . var_export(array_intersect_key($details, $fields + ['effective_date' => []]), true) . ";\n";
        token_get_all($detailsSource, TOKEN_PARSE);
        // Business details and helpers must exist before new pages are published.
        $changes = [$detailsPath => $detailsSource] + $changes;
    }

    // Refuse to overwrite files edited while the operator was answering prompts.
    foreach ($originals as $relativePath => $original) {
        $path = $root . '/' . $relativePath;
        $current = is_file($path) ? file_get_contents($path) : null;
        if (is_link($path) || $current !== $original) {
            throw new RuntimeException('A file changed during preparation: ' . $relativePath . '. No website files have been changed.');
        }
    }

    if ($changes) {
        $backupDirectory = dirname($root) . '/weddingza-policy-backup-'
            . gmdate('Ymd-His') . '-' . bin2hex(random_bytes(4));
        if (!mkdir($backupDirectory, 0700)) {
            throw new RuntimeException('Cannot prepare the policy backup.');
        }
        foreach ($changes as $relativePath => $updated) {
            $backupFile = $backupDirectory . '/' . $relativePath;
            if (!is_dir(dirname($backupFile)) && !mkdir(dirname($backupFile), 0700, true)) {
                throw new RuntimeException('Cannot prepare the backup for ' . $relativePath . '.');
            }
            $original = $originals[$relativePath];
            if ($original !== null && (file_put_contents($backupFile, $original) !== strlen($original) || !chmod($backupFile, 0600))) {
                throw new RuntimeException('Cannot back up ' . $relativePath . '.');
            }
            $staged[$relativePath] = $backupFile . '.new';
            $mode = $original !== null ? fileperms($root . '/' . $relativePath) & 0777 : 0644;
            if (file_put_contents($staged[$relativePath], $updated) !== strlen($updated)
                || !chmod($staged[$relativePath], $mode)) {
                throw new RuntimeException('Cannot stage ' . $relativePath . '.');
            }
        }
        foreach ($changes as $relativePath => $updated) {
            if (!rename($staged[$relativePath], $root . '/' . $relativePath)) {
                throw new RuntimeException('Cannot install ' . $relativePath . '.');
            }
            $installed[] = $relativePath;
        }
        echo "Privacy, Terms and Cancellation & Refund pages installed.\n";
        echo "Original files backed up in: " . $backupDirectory . "\n";
    } else {
        echo "The policy update and business details are already installed.\n";
    }
    echo "Database credentials, accounts and payment keys have not been changed.\n";
    echo "Open privacy.php, terms.php and cancellation.php to check your public details.\n";
    echo "Then run: php scripts/go-live-check.php\n";
} catch (Throwable $error) {
    $rollbackFailed = false;
    foreach (array_reverse($installed) as $relativePath) {
        if ($originals[$relativePath] === null) {
            $restored = unlink($root . '/' . $relativePath);
        } else {
            $restoreFile = $backupDirectory . '/' . $relativePath . '.restore';
            $mode = fileperms($root . '/' . $relativePath) & 0777;
            $restored = copy($backupDirectory . '/' . $relativePath, $restoreFile)
                && chmod($restoreFile, $mode) && rename($restoreFile, $root . '/' . $relativePath);
        }
        $rollbackFailed = $rollbackFailed || !$restored;
    }
    fwrite(STDERR, 'Update stopped: ' . $error->getMessage() . "\n");
    if ($installed) {
        fwrite(STDERR, $rollbackFailed
            ? 'Restore could not finish. Original files remain in: ' . $backupDirectory . "\n"
            : "Website changes were rolled back.\n");
    }
    exit(1);
} finally {
    if (is_resource($lock)) {
        flock($lock, LOCK_UN);
        fclose($lock);
    }
}
